+    }
+    for n in planned.iter().flat_map(|(l, _, _)| l.notes.iter()) {
+        if !notes.contains(n) {
+            notes.push(n.clone());
+        }
+    }
+    Ok(KernelPocketPlan { levels: planned, notes, strategy, heights, feeds })
+}

